function waitMs(ms) {
  return new Promise(resolve => setTimeout(resolve, Math.max(0, Number(ms) || 0)));
}

function defaultPermissionsForRole(role) {
  if (role === 'admin') return PERMISSION_CATALOG.slice();
  if (role === 'manager') return PERMISSION_CATALOG.filter(p => p !== 'credentials.manage');
  if (role === 'agent') return ['orders.view','orders.split','orders.final_action','binance.chat','p2p.profile.view','ads.view','ads.manage','accounts.view','accounts.use','accounting.view'];
  if (role === 'auditor') return ['dashboard.view','accounts.view','reports.view','accounting.view','activity.view','audit.view','orders.view','p2p.profile.view','ads.view'];
  return [];
}

function advertisementPermissionsForRole(role) {
  if (['admin', 'manager', 'agent'].includes(String(role || '').toLowerCase())) return ['ads.view', 'ads.manage'];
  if (String(role || '').toLowerCase() === 'auditor') return ['ads.view'];
  return [];
}

function p2pProfilePermissionsForRole(role) {
  const value = String(role || '').toLowerCase();
  if (['admin', 'manager'].includes(value)) return ['p2p.profile.view', 'p2p.profile.sync'];
  if (['agent', 'auditor'].includes(value)) return ['p2p.profile.view'];
  return [];
}

function userCanOverrideOrderAssignment(user) {
  return !!user && (userHasPermission(user, 'orders.assign') || userHasPermission(user, 'approvals.manage'));
}

function userIsAssignmentScoped(user) {
  return !!user && Number(user.agentId || 0) > 0 && userHasPermission(user, 'orders.view') && !userCanOverrideOrderAssignment(user);
}

function userIsAccountingScoped(user) {
  return !!user && Number(user.agentId || 0) > 0 && userHasPermission(user, 'accounting.view') && !userHasPermission(user, 'accounting.manage') && !userHasPermission(user, 'accounting.close');
}

function userReceivesManagerAudience(user) {
  return !!user && (userHasPermission(user, 'orders.assign') || userHasPermission(user, 'approvals.manage') || userHasPermission(user, 'agents.manage') || userHasPermission(user, 'settings.manage'));
}

function isPrivilegedOrderOperator(user) {
  return userCanOverrideOrderAssignment(user);
}

function normalizePermissions(value, role) {
  const incoming = Array.isArray(value) ? value : defaultPermissionsForRole(role);
  return Array.from(new Set(incoming.filter(p => PERMISSION_CATALOG.includes(p))));
}

function defaultUserRoles() {
  return [
    { id: 1, name: 'Super Admin', systemRole: 'admin', description: 'Full owner access', locked: true, permissions: PERMISSION_CATALOG.slice(), createdAt: nowIso() },
    { id: 2, name: 'Manager', systemRole: 'manager', description: 'Operations manager access', locked: true, permissions: defaultPermissionsForRole('manager'), createdAt: nowIso() },
    { id: 3, name: 'P2P Employee / Agent', systemRole: 'agent', description: 'Order handling employee access', locked: true, permissions: defaultPermissionsForRole('agent'), createdAt: nowIso() },
    { id: 4, name: 'Auditor', systemRole: 'auditor', description: 'Read-only audit/report access', locked: true, permissions: defaultPermissionsForRole('auditor'), createdAt: nowIso() }
  ];
}

function roleProfileById(id, target = db) { return (target.userRoles || []).find(r => Number(r.id) === Number(id)) || null; }
function defaultRoleProfileIdFor(systemRole, target = db) {
  const found = (target.userRoles || []).find(r => r.systemRole === systemRole);
  return found ? found.id : null;
}
function permissionsFromRoleProfile(roleProfileId, fallbackRole, target = db) {
  const profile = roleProfileById(roleProfileId, target);
  return normalizePermissions(profile ? profile.permissions : null, profile ? profile.systemRole : fallbackRole);
}

function userHasPermission(user, permission) {
  if (!user) return false;
  const permissions = normalizePermissions(Array.isArray(user.permissions) ? user.permissions : [], user.role);
  if (permissions.includes(permission)) return true;
  return Object.entries(PERMISSION_IMPLICATIONS).some(([granted, implied]) => permissions.includes(granted) && implied.includes(permission));
}

function binanceAccountGlobalPermissionSet(user = {}) {
  return new Set(BINANCE_ACCOUNT_PERMISSION_CATALOG.filter(permission => userHasPermission(user, permission)));
}

function normalizeBinanceCredentialPermissions(value = [], user = {}, target = db) {
  const credentials = Array.isArray(target?.apiCredentials) ? target.apiCredentials : [];
  const knownIds = new Set(credentials.map(item => Number(item.id)).filter(Boolean));
  const globalPermissions = binanceAccountGlobalPermissionSet(user);
  let rows = value;
  if (!Array.isArray(rows) && rows && typeof rows === 'object') {
    rows = Object.entries(rows).map(([credentialId, permissions]) => ({ credentialId: Number(credentialId), permissions }));
  }
  if (!Array.isArray(rows)) rows = [];
  const merged = new Map();
  rows.forEach(row => {
    const credentialId = Number(row?.credentialId ?? row?.id ?? 0);
    if (!credentialId || !knownIds.has(credentialId)) return;
    const incoming = Array.isArray(row?.permissions) ? row.permissions : String(row?.permissions || '').split(',');
    const allowed = incoming.filter(permission => BINANCE_ACCOUNT_PERMISSION_CATALOG.includes(permission) && globalPermissions.has(permission));
    if (!merged.has(credentialId)) merged.set(credentialId, new Set());
    allowed.forEach(permission => merged.get(credentialId).add(permission));
  });
  return [...merged.entries()]
    .map(([credentialId, permissions]) => ({ credentialId, permissions: BINANCE_ACCOUNT_PERMISSION_CATALOG.filter(permission => permissions.has(permission)) }))
    .filter(row => row.permissions.length)
    .sort((a, b) => a.credentialId - b.credentialId);
}

function binanceCredentialPermissionRowsForUser(user = {}, target = db) {
  return normalizeBinanceCredentialPermissions(user.binanceCredentialPermissions || [], user, target);
}

function userHasBinanceCredentialPermission(user, credentialId, permission, target = db) {
  if (!user || !credentialId || !BINANCE_ACCOUNT_PERMISSION_CATALOG.includes(permission)) return false;
  if (!userHasPermission(user, permission)) return false;
  const row = binanceCredentialPermissionRowsForUser(user, target).find(item => Number(item.credentialId) === Number(credentialId));
  if (!row) return false;
  if (row.permissions.includes(permission)) return true;
  return Object.entries(BINANCE_ACCOUNT_PERMISSION_IMPLICATIONS).some(([granted, implied]) => row.permissions.includes(granted) && implied.includes(permission));
}

function binanceCredentialIdsForUserPermission(user = {}, permission, options = {}) {
  const target = options.target || db;
  const includeDisabled = options.includeDisabled === true;
  const credentials = Array.isArray(target?.apiCredentials) ? target.apiCredentials : [];
  return credentials
    .filter(item => includeDisabled || !item.disabled)
    .filter(item => userHasBinanceCredentialPermission(user, item.id, permission, target))
    .map(item => Number(item.id));
}

function binanceCredentialP2pIdentity(credential = {}, target = db) {
  if (!credential || !Number(credential.id || 0)) {
    return { p2pUsername: '', nickname: '', displayName: '', accountName: '', userNo: '', merchantNo: '', profileSyncedAt: null };
  }
  const credentialId = Number(credential.id);
  const profiles = Array.isArray(target?.ownerP2pProfiles) ? target.ownerP2pProfiles : [];
  let profile = profiles.find(item => Number(item?.credentialId || 0) === credentialId) || null;
  if (!profile) {
    const orderedIds = [...(target?.apiCredentials || [])].sort((a, b) => {
      const at = Date.parse(a.createdAt || '') || 0;
      const bt = Date.parse(b.createdAt || '') || 0;
      return at - bt || Number(a.id || 0) - Number(b.id || 0);
    }).map(item => Number(item.id || 0)).filter(Boolean);
    if (credentialId === Number(orderedIds[0] || 0) && target?.ownerP2pProfile && typeof target.ownerP2pProfile === 'object') profile = target.ownerP2pProfile;
  }
  const accountName = cleanStr(credential.name || `API ${credential.id}`, 120);
  const p2pUsername = cleanStr(profile?.nickname || credential.ownerP2pNickname || '', 120);
  const userNo = cleanStr(profile?.userNo || credential.ownerP2pUserNo || '', 120);
  const merchantNo = cleanStr(profile?.merchantNo || credential.ownerP2pMerchantNo || '', 120);
  return {
    p2pUsername,
    nickname: p2pUsername,
    displayName: p2pUsername || accountName,
    accountName,
    userNo,
    merchantNo,
    profileSyncedAt: profile?.syncedAt || credential.ownerP2pProfileLastSyncAt || null
  };
}

function binanceCredentialOptionsForUser(user = {}, permission = null, options = {}) {
  const target = options.target || db;
  const includeDisabled = options.includeDisabled !== false;
  const rows = binanceCredentialPermissionRowsForUser(user, target);
  const grants = new Map(rows.map(row => [Number(row.credentialId), row.permissions.slice()]));
  return [...(target?.apiCredentials || [])]
    .filter(item => includeDisabled || !item.disabled)
    .filter(item => !permission || userHasBinanceCredentialPermission(user, item.id, permission, target))
    .sort((a, b) => {
      const at = Date.parse(a.createdAt || '') || 0;
      const bt = Date.parse(b.createdAt || '') || 0;
      return at - bt || Number(a.id || 0) - Number(b.id || 0);
    })
    .map(item => {
      const identity = binanceCredentialP2pIdentity(item, target);
      return {
        id: Number(item.id),
        name: identity.accountName,
        accountName: identity.accountName,
        displayName: identity.displayName,
        p2pUsername: identity.p2pUsername,
        nickname: identity.nickname,
        userNo: identity.userNo,
        merchantNo: identity.merchantNo,
        profileSyncedAt: identity.profileSyncedAt,
        status: item.disabled ? 'disabled' : cleanStr(item.status || 'saved', 40),
        disabled: Boolean(item.disabled),
        createdAt: item.createdAt || null,
        permissions: grants.get(Number(item.id)) || []
      };
    });
}

function resolveBinanceCredentialForUser(user = {}, requestedId = 0, permission, options = {}) {
  const target = options.target || db;
  const includeDisabled = options.includeDisabled === true;
  const optionsForUser = binanceCredentialOptionsForUser(user, permission, { target, includeDisabled });
  const wanted = Number(requestedId || 0);
  const option = wanted ? optionsForUser.find(item => Number(item.id) === wanted) : optionsForUser[0];
  if (!option) return null;
  return (target.apiCredentials || []).find(item => Number(item.id) === Number(option.id)) || null;
}

function syncLegacyP2pCredentialIds(user = {}, target = db) {
  user.allowedP2pCredentialIds = binanceCredentialPermissionRowsForUser(user, target)
    .filter(row => row.permissions.includes('p2p.profile.view'))
    .map(row => Number(row.credentialId));
  return user.allowedP2pCredentialIds;
}

function validateGrantedBinanceCredentialPermissions(actor, targetUser, requestedRows, target = db) {
  const normalized = normalizeBinanceCredentialPermissions(requestedRows, targetUser, target);
  for (const row of normalized) {
    for (const permission of row.permissions) {
      if (!userHasBinanceCredentialPermission(actor, row.credentialId, permission, target)) {
        const error = new Error(`You cannot grant ${permission} for Binance account ${row.credentialId}.`);
        error.statusCode = 403;
        throw error;
      }
    }
  }
  return normalized;
}

function validateGrantedGlobalPermissions(actor, requestedPermissions, role) {
  const normalized = normalizePermissions(requestedPermissions, role);
  const denied = normalized.filter(permission => !userHasPermission(actor, permission));
  if (denied.length) {
    const error = new Error(`You cannot grant permissions you do not have: ${denied.join(', ')}`);
    error.statusCode = 403;
    throw error;
  }
  return normalized;
}


