function ensureOrderFinancials(order) {
  if (!order) return order;
  order.fiatUnit = order.fiatUnit || 'BDT';
  order.fiatAmount = positiveNum(order.fiatAmount || order.amount || 0);
  order.amount = order.fiatAmount;
  order.rate = positiveNum(order.rate || 0);
  order.asset = cleanStr(order.asset || 'USDT', 30).toUpperCase();
  order.assetAmount = positiveNum(order.assetAmount || (order.rate ? round2(order.fiatAmount / order.rate) : 0));
  const assetSummary = deriveOrderAssetSummary(order);
  order.assetFee = assetSummary.fee;
  order.totalAssetAmount = assetSummary.totalQuantity;
  order.netAssetAmount = assetSummary.netQuantity;
  order.paymentTimeLimitMinutes = positiveNum(order.paymentTimeLimitMinutes || 15);
  order.paymentStartedAt = order.paymentStartedAt || order.createdAt || nowIso();
  order.paymentDeadlineAt = order.paymentDeadlineAt || addMinutesIso(order.paymentStartedAt, order.paymentTimeLimitMinutes);
  order.counterpartyStats = { ...emptyCounterpartyStats(), ...(order.counterpartyStats || {}) };
  if (!Array.isArray(order.counterpartyStats.feedbackComments)) order.counterpartyStats.feedbackComments = [];
  if (!order.counterpartyName) order.counterpartyName = order.counterpartyStats.nickname || '';
  order.counterpartyRealName = counterpartyRealNameForOrder(order);
  return order;
}

